//! 📸️ The EPW editor exports its original native snapshot with exact byte parity and funded cancellation.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,Operation,OperationId,Generation,RevisionId,JobOutcomeBorrow,JobOutcomeKind};
use semio_framework_plugin::{ArtifactMediaExportJobRequest,ArtifactReservedJob,EditorApp};
use semio_framework_plugin::app::{ArtifactOutputChunks,ArtifactMediaExportCredit,ArtifactMediaExportCompletion};
use semio_framework_plugin::native_snapshot_export::{NativeSnapshotPackExportJob,SNAPSHOT_PACK_PORT,SNAPSHOT_PACK_TOOL,SNAPSHOT_PACK_MIME};
use semio_framework_value::{RetainedCloneGrant,retirement::{OwnedValueRetirementFactory,controlled::ControlledRetirement},ToValue};
use semio_framework_pack::snapshot::ArtifactPack;
use std::sync::Arc;
#[global_allocator]
static ORIGINAL_EXPORT_HEAP:semio_framework_trace_memory_testing::RequestedAllocator=semio_framework_trace_memory_testing::RequestedAllocator;
fn clock()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:4_000_000,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:96}}
fn turn()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:96}}
fn original<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<R,semio_framework_job::OriginalTurnFailure>)->R{
 let before=caller.cumulative_receipt();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,run));let after=caller.cumulative_receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));answer.unwrap()
}
#[test]
fn original_epw_native_snapshot_export_matches_pack_and_json_and_closes_cancelled_sources(){
 for cancelled in [false,true]{
  let operation=Operation::new(OperationId(if cancelled{97002}else{97001}),RevisionId(7),Generation(3),11);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,stock(),clock,u64::MAX,4_000_000);let mut decoder=OriginalJobDecodeOwner::empty();let source=Arc::new(<EpwEditor as ArtifactEditor>::reference_birth().expect("explicit reference snapshot producer")().expect("the reference snapshot births"));let expected=source.encode_pack().unwrap();let expected_json=serde_json::to_value(source.to_value()).unwrap();
  let factory:Arc<dyn semio_framework_value::ArtifactOwnedValueRetirementFactory<EpwSnapshot>>=Arc::new(OwnedValueRetirementFactory::<EpwSnapshot>::default());let mut supplier=semio_framework_plugin_ownership::store_lifecycle::ArtifactMediaSnapshotSource::empty();
  for _ in 0..16{if supplier.ready(){break}caller.turn(turn(),|cx|supplier.admit_step(&factory,||Arc::clone(&source),cx)).unwrap();}assert!(supplier.ready());let(mut snapshot,mut lease,mut retention)=(None,None,None);caller.turn(turn(),|cx|supplier.handoff(&mut snapshot,&mut lease,&mut retention,cx)).unwrap();assert!(supplier.terminal_is_empty());
  let completion=ArtifactMediaExportCompletion::new();let credit=ArtifactMediaExportCredit::new(ArtifactOutputChunks::MAXIMUM_TOTAL_BYTES);let chunks=ArtifactOutputChunks::new(ArtifactOutputChunks::MAXIMUM_TOTAL_BYTES);let mut request=Some(ArtifactMediaExportJobRequest::<EditorApp<EpwEditor>>{source_identity:(operation.operation,operation.generation),retained:turn(),operation,tool_id:SNAPSHOT_PACK_TOOL.into(),parent_document_id:"original-weather".into(),canonical_base_revision:[7;32],snapshot:snapshot.take().unwrap(),snapshot_close:lease.take().unwrap(),port:SNAPSHOT_PACK_PORT.into(),output_credit:credit.clone(),output_chunks:chunks.clone(),completion:completion.clone()});let mut body:Option<Box<dyn ArtifactReservedJob+Send>>=None;
  let denied=RetainedCloneGrant{maximum_items:0,..turn()};assert!(!original(&mut caller,&mut decoder,denied,|cx|NativeSnapshotPackExportJob::<EditorApp<EpwEditor>>::admit_original(&mut request,&mut body,cx)));assert!(request.is_some()&&body.is_none());
  for _ in 0..8{if original(&mut caller,&mut decoder,turn(),|cx|NativeSnapshotPackExportJob::<EditorApp<EpwEditor>>::admit_original(&mut request,&mut body,cx)){break}}assert!(request.is_none());
  let first=original(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:1,..turn()},|cx|body.as_mut().unwrap().step(cx).map(|outcome|outcome.map(JobOutcomeBorrow::into_descriptor)));assert!(first.is_none());
  let mut foreign=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,stock(),clock,u64::MAX,4_000_000);let mut foreign_decoder=OriginalJobDecodeOwner::empty();let before=foreign.cumulative_receipt();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn_with_decoder(turn(),&mut foreign_decoder,|cx|body.as_mut().unwrap().step(cx).map(|outcome|outcome.map(JobOutcomeBorrow::into_descriptor))));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(foreign.cumulative_receipt(),before);assert!(foreign_decoder.terminal_is_empty());drop(foreign_decoder);foreign.retire(turn());
  if cancelled{body.as_mut().unwrap().begin_close();}
  let mut terminal=false;for _index in 0..20000{if cancelled{break}let descriptor=original(&mut caller,&mut decoder,turn(),|cx|body.as_mut().unwrap().step(cx).map(|outcome|outcome.map(JobOutcomeBorrow::into_descriptor)));if let Some(mut descriptor)=descriptor{terminal=matches!(descriptor.kind(),JobOutcomeKind::Complete);caller.turn(turn(),|cx|{let receipt=descriptor.acknowledge(cx.retained_grant()).progress();cx.consume_retained(receipt)?;cx.consume_fuel(receipt.copied_items as u64);Ok(())}).unwrap();}if terminal{break}}
  if !cancelled{assert!(terminal);let result=completion.take().unwrap().unwrap().unwrap();assert_eq!(result.mime_type,SNAPSHOT_PACK_MIME);assert_eq!(credit.bytes(),result.schema.len()+result.chunks.bytes());let mut actual=Vec::new();while let Some(page)=result.chunks.take_chunk().unwrap(){actual.extend_from_slice(&page)}assert_eq!(actual,expected);let decoded=EpwSnapshot::decode_pack(&actual).unwrap();assert_eq!(serde_json::to_value(decoded.to_value()).unwrap(),expected_json);drop(result);}else{body.as_mut().unwrap().begin_close();}
  for _ in 0..20000{if body.as_ref().unwrap().terminal_is_empty(){break}original(&mut caller,&mut decoder,turn(),|cx|body.as_mut().unwrap().close_step(cx));}assert!(body.as_ref().unwrap().terminal_is_empty());let bytes=std::mem::size_of_val(&**body.as_ref().unwrap());caller.turn(turn(),|cx|{drop(body.take());cx.consume_retained(semio_framework_value::RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap();
  drop(source);drop(factory);for _ in 0..20000{if retention.as_ref().unwrap().terminal_is_empty(){break}caller.turn(turn(),|cx|{let grant=cx.retained_grant();retention.as_mut().unwrap().close_step(cx,grant)}).unwrap();}assert!(retention.as_ref().unwrap().terminal_is_empty());drop(retention);drop(supplier);
  let mut outputs=Some(ControlledRetirement::new((completion,credit,chunks)).unwrap_or_else(|_|panic!("native output handles support controlled close")));for _ in 0..20000{if outputs.as_ref().unwrap().terminal_is_empty(){break}caller.turn(turn(),|cx|{let d=outputs.as_ref().unwrap().selected_demand(cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,d,|grant|outputs.as_mut().unwrap().step(grant))}).unwrap();}assert!(outputs.as_ref().unwrap().terminal_is_empty());drop(outputs.take());
  while !decoder.terminal_is_empty(){caller.turn(turn(),|cx|{let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,d,|grant|decoder.close_step(grant))}).unwrap();}drop(decoder);caller.retire(turn());
 }
}
